mapper.select:
SELECT COUNT(*)
FROM TB_PM07M01
WHERE 1=1

AND ST_DT <= #{reqDtTo}
AND ED_DT >= #{reqDtFrom}


AND VAC_TYPE_CD = #{vacTypeCd}


AND SANCTN_STS = #{sanctnSts}


AND REQ_ID = #{reqId}


AND (EXISTS (SELECT 1 FROM TB_CM06M01 U WHERE U.ID = TB_PM07M01.REQ_ID AND U.NAME LIKE '%' || #{reqIdNm} || '%') OR REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR REQ_ID LIKE '%' || #{reqIdNm} || '%')


AND REQ_DEPT_ID = #{reqDeptId}


AND EXISTS (SELECT 1 FROM TB_CM04M01 D WHERE D.DEPT_ID = TB_PM07M01.REQ_DEPT_ID AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%')

SELECT CO_CD, REQ_NO, REQ_DT, REQ_TITL, REQ_ID, REQ_DEPT_ID, VAC_TYPE_CD, (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = VAC_TYPE_CD) AS VAC_TYPE_NM, FN_CM06M01_ID_TO_NM(REQ_ID) AS REQ_ID_NM, (SELECT DEPT_NM FROM TB_CM04M01 WHERE DEPT_ID = REQ_DEPT_ID) AS REQ_DEPT_NM, (SELECT SALES_AREA FROM TB_CM06M01 WHERE ID = REQ_ID) AS REQ_SALES_AREA, AMPM_CD, (SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = AMPM_CD) AS AMPM_NM, TO_CHAR(TO_DATE(ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, ST_DT AS RAW_ST_DT, ED_DT AS RAW_ED_DT, TO_CHAR(TO_DATE(ST_TM, 'HH24MI'), 'HH24:MI') AS ST_TM, TO_CHAR(TO_DATE(ED_TM, 'HH24MI'), 'HH24:MI') AS ED_TM, VAC_DAYS, DEDUCT_DAYS, REQ_RMK, NVL(( SELECT CASE WHEN SUM(CASE WHEN W.TODO_CF_DT IS NOT NULL AND (W.SANCTN_STTUS = 'N' OR W.SANCTN_STTUS = 'R' OR W.SANCTN_STTUS = '4') THEN 1 ELSE 0 END) > 0 THEN 'RTN' WHEN COUNT(W.TODO_KEY) = 0 THEN 'TEMP' WHEN COUNT(W.TODO_KEY) > 0 AND COUNT(W.TODO_KEY) = SUM(CASE WHEN W.TODO_CF_DT IS NOT NULL AND W.SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) THEN 'END' WHEN SUM(CASE WHEN W.SANCTN_SN > 1 AND W.TODO_CF_DT IS NOT NULL AND W.SANCTN_STTUS != 'N' THEN 1 ELSE 0 END) > 0 THEN 'ING' ELSE 'REQ' END FROM TB_WB20M03 W WHERE W.TODO_NO = TB_PM07M01.REQ_NO AND W.TODO_DIV1_CODE_ID = 'TODODIV20' ), NVL(SANCTN_STS, 'TEMP')) AS SANCTN_STS, WORK_RPT_YN, CREAT_ID, TO_CHAR(CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM07M01 WHERE 1=1
AND ST_DT <= #{reqDtTo} AND ED_DT >= #{reqDtFrom}
AND VAC_TYPE_CD = #{vacTypeCd}
AND REQ_ID = #{reqId}
AND (EXISTS (SELECT 1 FROM TB_CM06M01 U WHERE U.ID = TB_PM07M01.REQ_ID AND U.NAME LIKE '%' || #{reqIdNm} || '%') OR REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND REQ_DEPT_ID = #{reqDeptId}
AND EXISTS (SELECT 1 FROM TB_CM04M01 D WHERE D.DEPT_ID = TB_PM07M01.REQ_DEPT_ID AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%')
ORDER BY ST_DT ASC, REQ_NO ASC

SELECT * FROM ( SELECT ROWNUM AS RNUM, T.* FROM ( SELECT M.CO_CD, M.REQ_NO, M.REQ_DT, M.REQ_TITL, M.REQ_ID, M.REQ_DEPT_ID, M.VAC_TYPE_CD, C1.CODE_NM AS VAC_TYPE_NM, NVL(U.NAME, M.REQ_TITL) AS REQ_ID_NM, D.DEPT_NM AS REQ_DEPT_NM, M.AMPM_CD, TO_CHAR(TO_DATE(M.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ST_DT, TO_CHAR(TO_DATE(M.ED_DT, 'YYYYMMDD'), 'YYYY-MM-DD') AS ED_DT, TO_CHAR(TO_DATE(M.ST_TM, 'HH24MI'), 'HH24:MI') AS ST_TM, TO_CHAR(TO_DATE(M.ED_TM, 'HH24MI'), 'HH24:MI') AS ED_TM, M.VAC_DAYS, M.DEDUCT_DAYS, M.REQ_RMK, M.MNG_RMK, NVL(M.SANCTN_STS, 'TEMP') AS SANCTN_STS, M.WORK_RPT_YN, M.CREAT_ID, TO_CHAR(M.CREAT_DTTM, 'YYYY-MM-DD HH24:MI:SS') AS CREAT_DTTM FROM TB_PM07M01 M LEFT JOIN TB_CM06M01 U ON U.ID = M.REQ_ID LEFT JOIN TB_CM04M01 D ON D.DEPT_ID = M.REQ_DEPT_ID LEFT JOIN TB_CM05M01 C1 ON C1.CODE_ID = M.VAC_TYPE_CD WHERE 1=1
AND M.ST_DT <= #{reqDtTo} AND M.ED_DT >= #{reqDtFrom}
AND M.VAC_TYPE_CD = #{vacTypeCd}
AND M.REQ_ID = #{reqId}
AND (U.NAME LIKE '%' || #{reqIdNm} || '%' OR M.REQ_TITL LIKE '%' || #{reqIdNm} || '%' OR M.REQ_ID LIKE '%' || #{reqIdNm} || '%')
AND M.REQ_DEPT_ID = #{reqDeptId}
AND D.DEPT_NM LIKE '%' || #{reqDeptNm} || '%'
AND M.SANCTN_STS = #{sanctnSts}
ORDER BY D.DEPT_NM ASC, U.NAME ASC, M.ST_DT DESC, M.REQ_NO DESC ) T
WHERE ROWNUM <= #{lastIndex}
)
WHERE RNUM >= #{firstIndex}

SELECT COUNT(*)
FROM TB_PM07M02
WHERE CO_CD = #{coCd} AND YY = #{yy} AND USER_ID = #{userId}

SELECT T.CO_CD, T.YY, T.USER_ID, T.USER_NM, T.DEPT_NM, T.ENTER_DT, T.LEAVE_DT, T.GRANT_DAYS, T.USED_DAYS, (T.GRANT_DAYS - T.USED_DAYS) AS BALANCE_DAYS, T.AUTO_YN, T.RMK, T.VAC_INFO_LIST FROM ( SELECT M.CO_CD, M.YY, M.USER_ID, U.NAME AS USER_NM, D.DEPT_NM, NVL(D.SORT_NO, 9999) AS DEPT_SORT_NO, TO_CHAR(U.ENTER_DT, 'YYYY-MM-DD') AS ENTER_DT, TO_CHAR(U.LEAVE_DT, 'YYYY-MM-DD') AS LEAVE_DT, NVL(M.GRANT_DAYS, 0) AS GRANT_DAYS, NVL(( SELECT SUM(V.DEDUCT_DAYS) FROM TB_PM07M01 V WHERE V.CO_CD = M.CO_CD AND V.REQ_ID = M.USER_ID AND V.ST_DT LIKE M.YY || '%' AND V.SANCTN_STS = 'END' ), 0) AS USED_DAYS, ( SELECT LISTAGG( TO_CHAR(TO_DATE(V.ST_DT, 'YYYYMMDD'), 'YYYY-MM-DD') || CASE WHEN V.ED_DT IS NOT NULL AND V.ED_DT != V.ST_DT THEN '~' || TO_CHAR(TO_DATE(V.ED_DT, 'YYYYMMDD'), 'MM-DD') ELSE '' END || ' (' || NVL((SELECT CODE_NM FROM TB_CM05M01 WHERE CODE_ID = V.VAC_TYPE_CD), V.VAC_TYPE_CD) || ' ' || V.DEDUCT_DAYS || '일)', '; ' ) WITHIN GROUP (ORDER BY V.ST_DT ASC) FROM TB_PM07M01 V WHERE V.REQ_ID = M.USER_ID AND V.ST_DT LIKE M.YY || '%' AND V.SANCTN_STS = 'END' ) AS VAC_INFO_LIST, M.AUTO_YN, M.RMK FROM TB_PM07M02 M LEFT OUTER JOIN TB_CM06M01 U ON M.USER_ID = U.ID LEFT OUTER JOIN TB_CM04M01 D ON D.DEPT_ID = SUBSTR(NVL(U.VIEW_DEPT_ID, U.DEPT_ID), 1, 5) WHERE 1=1
AND M.YY = #{yy}
AND M.USER_ID = #{userId}
AND (U.NAME LIKE '%' || #{searchValue} || '%' OR M.USER_ID LIKE '%' || #{searchValue} || '%')
) T ORDER BY T.YY DESC, T.DEPT_SORT_NO ASC, T.DEPT_NM ASC, T.USER_NM ASC


SELECT COUNT(*)
FROM TB_WB20M03
WHERE TODO_NO = #{reqNo}

  AND TODO_FILE_TRGT_KEY = #{fileTrgtKey}

AND TODO_DIV1_CODE_ID = 'TODODIV20'
AND SANCTN_STTUS = 'Y'

/* 해당 문서(REQ_NO)의 순수 결재자(TODODIV20) 수 조회 */
SELECT COUNT(*)
FROM TB_WB20M03
WHERE TODO_NO = #{reqNo}
  AND TODO_DIV1_CODE_ID = 'TODODIV20'

